SELECT Currency,Kind,count() AS Payments,sum(Amount) AS Gross_minor_units FROM (SELECT toString(properties.transaction_id) AS ID,argMax(toString(properties.currency),timestamp) AS Currency,argMax(toString(properties.purchase_type),timestamp) AS Kind,max(toFloat(properties.amount_minor)) AS Amount FROM events WHERE event='purchase_verified' AND (properties.environment = 'production' AND properties.product = 'studio') AND properties.livemode=true AND toFloat(properties.amount_minor)>0 AND {filters} GROUP BY ID) GROUP BY Currency,Kind ORDER BY Payments DESC LIMIT 30
